<?php
require_once __DIR__.'/config.php';require_once __DIR__.'/includes/system_analytics.php';require_once __DIR__.'/includes/analytics_export.php';
header('Cache-Control: no-store, private, max-age=0');header('Pragma: no-cache');header('X-Content-Type-Options: nosniff');
try{$db=connectDb();anActor($db);if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');throw new DomainException('Use the authorized Analytics export buttons.');}if(!is_string($_POST['csrf_token']??null)||!hash_equals(workflowCsrfToken(),$_POST['csrf_token']))throw new DomainException('Refresh your session and try again.',403);foreach($_POST as$v)if(!is_string($v))throw new DomainException('Invalid analytics export input.');$scope=$_POST['scope']??'all';$format=$_POST['format']??'pdf';if(!in_array($format,['pdf','png'],true))throw new DomainException('Choose PDF or PNG.');$data=anCapture($db,$_POST,$scope==='all'?null:$scope);anExportGuard($data);session_write_close();anDownload($db,$data,$format);
}catch(DomainException $e){if(http_response_code()<400)http_response_code(in_array($e->getCode(),[401,403],true)?$e->getCode():422);header('Content-Type: application/json');echo json_encode(['error'=>$e->getMessage()]);}catch(Throwable $e){http_response_code(503);header('Content-Type: application/json');error_log('Analytics export: '.get_class($e));echo '{"error":"The complete analytics report could not be generated. Please try a narrower scope or period."}';}
